*** Begin Patch
*** Add File: /Users/pfleidi/entire/cli/.worktrees/feat/checkpoints-v2-explain/cmd/entire/cli/transcript/compact/parse.go
+package compact
+
+import (
+	"encoding/json"
+	"errors"
+	"strings"
+)
+
+type ParsedLine struct {
+	V          int
+	Agent      string
+	CLIVersion string
+	Type       string
+	Content    []ParsedContentBlock
+}
+
+type ParsedContentBlock struct {
+	Type  string
+	Text  string
+	Name  string
+	Input map[string]interface{}
+}
+
+func ParseLines(content []byte) ([]ParsedLine, error) {
+	trimmed := strings.TrimSpace(string(content))
+	if trimmed == "" {
+		return nil, nil
+	}
+
+	rawLines := strings.Split(trimmed, "\n")
+	parsed := make([]ParsedLine, 0, len(rawLines))
+
+	for _, rawLine := range rawLines {
+		lineText := strings.TrimSpace(rawLine)
+		if lineText == "" {
+			continue
+		}
+
+		var line transcriptLine
+		if err := json.Unmarshal([]byte(lineText), &line); err != nil {
+			return nil, err
+		}
+		if line.V == 0 || line.CLIVersion == "" {
+			return nil, errors.New("not compact transcript format")
+		}
+
+		entry := ParsedLine{
+			V:          line.V,
+			Agent:      line.Agent,
+			CLIVersion: line.CLIVersion,
+			Type:       line.Type,
+		}
+
+		if len(line.Content) > 0 {
+			var blocks []map[string]json.RawMessage
+			if err := json.Unmarshal(line.Content, &blocks); err == nil {
+				entry.Content = make([]ParsedContentBlock, 0, len(blocks))
+				for _, block := range blocks {
+					parsedBlock := ParsedContentBlock{}
+					_ = json.Unmarshal(block["type"], &parsedBlock.Type)
+					_ = json.Unmarshal(block["text"], &parsedBlock.Text)
+					_ = json.Unmarshal(block["name"], &parsedBlock.Name)
+					if inputJSON, ok := block["input"]; ok && len(inputJSON) > 0 {
+						_ = json.Unmarshal(inputJSON, &parsedBlock.Input)
+					}
+					entry.Content = append(entry.Content, parsedBlock)
+				}
+			}
+		}
+
+		parsed = append(parsed, entry)
+	}
+
+	return parsed, nil
+}
+
